262	    fields.forEach(f => { row[f] = idx[f] >= 0 ? v[idx[f]] : ''; });
263	    rows.push(row);
264	  }
265	  let created = 0, merged = 0;
266	  for (let i = 0; i < rows.length; i += PCB_BATCH) {
267	    const res = UrlFetchApp.fetch(url, {
268	      method: 'post', contentType: 'application/json', muteHttpExceptions: true,
269	      headers: { 'x-sub-raw-sync-secret': secret },
270	      payload: JSON.stringify({ rows: rows.slice(i, i + PCB_BATCH) })
271	    });
272	    if (res.getResponseCode() !== 200) throw new Error('Portal said ' + res.getResponseCode() + ': ' + res.getContentText().slice(0, 300));
273	    const j = JSON.parse(res.getContentText()); created += j.created || 0; merged += j.merged || 0;
274	  }
275	  console.log('Paytm callback sync: ' + rows.length + ' rows, new requests ' + created + ', repeats within 24h ' + merged);
276	}
