299	/**
300	 * Pi Commerce — SMB Daily Tracker -> CSM workspace daily sync
301	 *
302	 * Replaces the Kunal tracker script. Sends the full "Sub Raw" and "AdsRun Raw" tabs to the
303	 * portal every morning; the portal builds the CSM queues (Ads About to End, Ads Ended,
304	 * Cancelled / Expired, Onboarding Lost) from them.
305	 *
306	 * Sub Raw columns used: merchant_cust_id, subscription_status, check sub status, cancelled_at,
307	 * expected_renewal_due_date, renewal_date, completed_ads_count, current_wallet_balance,
308	 * merchant_name, phone_number, category, sub_category, mcc_code, sub_first_date.
309	 *
310	 * Add this file to the same Apps Script project as the Sub Raw onboarding sync.
311	 * Script Properties required:
312	 *   PI_COMMERCE_CSM_SYNC_URL         e.g. https://<portal-domain>/api/internal/csm-sync
313	 *   PI_COMMERCE_SUB_RAW_SYNC_SECRET  (already set for the onboarding sync; same secret)
314	 *
315	 * Run installDailyCsmSyncTrigger() once. Use runCsmSync() any time to refresh by hand.
316	 */
317	
318	const CSM_SYNC = {
319	  SUB_SHEET: 'Sub Raw',
320	  ADS_SHEET: 'AdsRun Raw',
321	  TIMEZONE: 'Asia/Kolkata',
322	  REFRESH_HOUR: 9,  // after the AdsRun Raw Gmail import (~8:55 AM)
323	  BATCH_SIZE: 500,
324	};
