326	function runCsmSync() {
327	  const props = PropertiesService.getScriptProperties();
328	  const url = String(props.getProperty('PI_COMMERCE_CSM_SYNC_URL') || '').trim();
329	  const [redacted] || '').trim();
330	  if (!url || !secret) {
331	    throw new Error('Missing PI_COMMERCE_CSM_SYNC_URL or PI_COMMERCE_SUB_RAW_SYNC_SECRET in Script Properties.');
332	  }
333	
334	  const ss = SpreadsheetApp.getActiveSpreadsheet();
335	  const subs = readSubs_(ss.getSheetByName(CSM_SYNC.SUB_SHEET));
336	  const ads = readAds_(ss.getSheetByName(CSM_SYNC.ADS_SHEET));
337	
338	  const start = csmPost_(url, secret, { action: 'start' });
339	  const runId = start.runId;
340	  for (let i = 0; i < subs.length; i += CSM_SYNC.BATCH_SIZE) {
341	    csmPost_(url, secret, { action: 'subs', runId: runId, rows: subs.slice(i, i + CSM_SYNC.BATCH_SIZE) });
342	  }
343	  for (let i = 0; i < ads.length; i += CSM_SYNC.BATCH_SIZE) {
344	    csmPost_(url, secret, { action: 'ads', runId: runId, rows: ads.slice(i, i + CSM_SYNC.BATCH_SIZE) });
345	  }
346	  const done = csmPost_(url, secret, {
347	    action: 'finish', runId: runId, expectedSubs: subs.length, expectedAds: ads.length,
348	  });
349	  console.log('CSM sync complete: ' + JSON.stringify(done));
350	  return done;
351	}
