366	/** One row per merchant (the last Sub Raw row wins, as in the old tracker). */
367	function readSubs_(sheet) {
368	  if (!sheet) throw new Error('Tab "' + CSM_SYNC.SUB_SHEET + '" was not found.');
369	  const data = readTab_(sheet, ['merchant_cust_id', 'subscription_status']);
370	  const byCust = {};
371	  data.rows.forEach(function (row, i) {
372	    const custId = cell_(row, data.col, 'merchant_cust_id');
373	    if (!custId) return;
374	    byCust[custId] = {
375	      customerId: custId,
376	      status: cell_(row, data.col, 'subscription_status').toUpperCase(),
377	      merchantName: cell_(row, data.col, 'merchant_name'),
378	      phone: cell_(row, data.col, 'phone_number'),
379	      category: cell_(row, data.col, 'category'),
