394	
395	/** Every ad row. */
396	function readAds_(sheet) {
397	  if (!sheet) throw new Error('Tab "' + CSM_SYNC.ADS_SHEET + '" was not found.');
398	  const data = readTab_(sheet, ['CustID', 'Ad_Status', 'Ad_End_Date', 'Clicks']);
399	  const out = [];
