401	    const custId = cell_(row, data.col, 'CustID');
402	    if (!custId) return;
403	    const raw = data.raw[i];
404	    out.push({
405	      customerId: custId,
406	      clientId: cell_(row, data.col, 'Client_ID'),
407	      mid: cell_(row, data.col, 'MID'),
408	      merchantName: cell_(row, data.col, 'Merchant_Name'),
409	      phone: cell_(row, data.col, 'PhoneNo'),
410	      category: cell_(row, data.col, 'Category'),
411	      subCategory: cell_(row, data.col, 'Sub_Category'),
412	      onboardedDate: date_(raw[data.col.Onboarded_Date]),
413	      creativeName: cell_(row, data.col, 'Ad_Creative_Name'),
414	      description: cell_(row, data.col, 'Ad_Description'),
415	      adStatus: cell_(row, data.col, 'Ad_Status').toUpperCase(),
416	      budget: cell_(row, data.col, 'Ad_Budget'),
417	      startDate: date_(raw[data.col.Ad_Start_Date]),
418	      endDate: date_(raw[data.col.Ad_End_Date]),
