430	
431	/** Ads ID: header "Ads ID" / "Ad_ID" / "AdsID" (col U of AdsRun Raw; the same ID as col A of
432	 *  meta_failed_ads and Ad_ID in Onboardings_Updated_List). Never Meta_AD_ID. Column U if no header matches. */
433	function adId_(row, col) {
434	  const names = ['ads_id', 'ad_id', 'adsid', 'adid'];
435	  for (let i = 0; i < names.length; i++) if (col[names[i]] !== undefined) return cell_(row, col, names[i]).replace(/\.0$/, '');
436	  return String(row[20] == null ? '' : row[20]).trim().replace(/\.0$/, '');
437	}
438	
439	function readTab_(sheet, required) {
440	  const range = sheet.getDataRange();
441	  const display = range.getDisplayValues();
442	  const raw = range.getValues();
443	  if (display.length < 2) throw new Error('No data rows in "' + sheet.getName() + '".');
444	  const col = {};
445	  // Headers are matched as written and also normalised ("Check Sub Status" -> check_sub_status).
446	  display[0].forEach(function (h, i) {
447	    const k = String(h || '').trim();
448	    if (!k) return;
449	    if (col[k] === undefined) col[k] = i;
450	    const n = k.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
451	    if (col[n] === undefined) col[n] = i;
452	  });
453	  const missing = required.filter(function (h) { return col[h] === undefined; });
454	  if (missing.length) throw new Error('Missing columns in "' + sheet.getName() + '": ' + missing.join(', '));
455	  return { col: col, rows: display.slice(1), raw: raw.slice(1) };
456	}
457	
458	function cell_(row, col, header) {
459	  return col[header] === undefined ? '' : String(row[col[header]] || '').trim();
460	}
461	
462	/** A plain number from a cell, ignoring ₹ signs and commas. Blank when there is no number. */
463	function num_(value) {
464	  if (typeof value === 'number') return isNaN(value) ? '' : value;
465	  const t = String(value === undefined || value === null ? '' : value).replace(/[^0-9.\-]/g, '');
466	  return t === '' || isNaN(Number(t)) ? '' : Number(t);
467	}
468	
469	function date_(value) {
470	  if (value === undefined || value === null || value === '') return '';
471	  if (Object.prototype.toString.call(value) === '[object Date]' && !isNaN(value)) {
472	    return Utilities.formatDate(value, CSM_SYNC.TIMEZONE, 'yyyy-MM-dd');
473	  }
474	  const t = String(value).trim();
475	  if (/^\d{4}-\d{2}-\d{2}/.test(t)) return t.slice(0, 10);
476	  const d = new Date(t);
477	  return isNaN(d) ? '' : Utilities.formatDate(d, CSM_SYNC.TIMEZONE, 'yyyy-MM-dd');
478	}
479	
480	function csmPost_(url, secret, payload) {
481	  const res = UrlFetchApp.fetch(url, {
482	    method: 'post',
483	    contentType: 'application/json',
484	    headers: { 'x-sub-raw-sync-secret': secret },
485	    payload: JSON.stringify(payload),
486	    muteHttpExceptions: true,
487	  });
488	  const code = res.getResponseCode();
489	  const text = res.getContentText();
490	  if (code < 200 || code >= 300) throw new Error('CSM sync failed (' + payload.action + ', HTTP ' + code + '): ' + text);
491	  return JSON.parse(text);
492	}
