500	// Daily push of the SMB Daily Tracker's Sub Raw and AdsRun Raw tabs (scripts/csm-sync.gs).
501	// Protocol: start → subs / ads batches → finish. Rows are written under a new run and only
502	// become visible when finish succeeds, so a failed or partial push never replaces good data.
503	// Uses the same secret as the Sub Raw onboarding sync.
504	
505	function sameSecret(a:string,b:string){
506	  const aa=Buffer.from(a); const bb=Buffer.from(b);
507	  return aa.length===bb.length && timingSafeEqual(aa,bb);
508	}
509	const iso=(v:unknown)=>{const t=String(v??'').trim();return /^\d{4}-\d{2}-\d{2}$/.test(t)?t:null;};
510	const num=(v:unknown)=>{const t=String(v??'').replace(/[^0-9.\-]/g,'').trim();if(!t)return null;const n=Number(t);return Number.isFinite(n)?n:null;};
511	const txt=(v:unknown)=>{const t=String(v??'').trim();return t||null;};
512	const custId=(v:unknown)=>{const t=String(v??'').trim().replace(/\.0$/,'');return /^\d+$/.test(t)?t:null;};
