514	export async function POST(req:Request){
515	  const configured=process.env.SUB_RAW_SYNC_SECRET||'';
516	  const supplied=req.headers.get('x-sub-raw-sync-secret')||'';
517	  if(!configured||!supplied||!sameSecret(configured,supplied)) return NextResponse.json({error:'Unauthorized'},{status:401});
518	  const body:any=await req.json().catch(()=>null);
519	  const action=String(body?.action||'');
520	  const sql=db();
521	
522	  if(action==='start'){
523	    await sql`UPDATE csm_sync_runs SET status='failed',finished_at=now(),note='abandoned' WHERE status='running' AND started_at<now()-interval '1 hour'`;
524	    const rows=await sql`INSERT INTO csm_sync_runs(status) VALUES('running') RETURNING id`;
525	    return NextResponse.json({ok:true,runId:Number(rows[0].id)});
526	  }
527	
528	  const runId=Number(body?.runId);
529	  if(!Number.isInteger(runId)) return NextResponse.json({error:'runId is required'},{status:400});
530	  const run=await sql`SELECT status FROM csm_sync_runs WHERE id=${runId}`;
531	  if(run[0]?.status!=='running') return NextResponse.json({error:'This sync run is not open.'},{status:409});
532	  const input:any[]=Array.isArray(body?.rows)?body.rows:[];
533	  if(input.length>1000) return NextResponse.json({error:'Send at most 1000 rows per request.'},{status:400});
534	
535	  if(action==='subs'){
536	    const rows:any[]=[]; const invalid:number[]=[];
537	    for(const r of input){
538	      const id=custId(r.customerId); const status=String(r.status||'').trim().toUpperCase();
539	      if(!id||!['ACTIVE','CANCELLED','EXPIRED'].includes(status)){invalid.push(Number(r.sourceRow)||0);continue;}
540	      rows.push({customer_id:id,status,merchant_name:txt(r.merchantName),phone_number:txt(r.phone),category:txt(r.category),sub_category:txt(r.subCategory),mcc:txt(r.mcc),sub_first_date:iso(r.subFirstDate),
541	        check_sub_status:txt(r.checkSubStatus),cancelled_at:iso(r.cancelledAt),expected_renewal_due_date:iso(r.renewalDueDate),renewal_date:iso(r.renewalDate),
542	        completed_ads_count:num(r.completedAdsCount),wallet_balance:num(r.walletBalance)});
543	    }
544	    if(rows.length) await sql`
545	      INSERT INTO merchant_subscriptions(sync_run_id,customer_id,status,merchant_name,phone_number,category,sub_category,mcc,sub_first_date,
546	        check_sub_status,cancelled_at,expected_renewal_due_date,renewal_date,completed_ads_count,wallet_balance)
547	      SELECT ${runId},x.customer_id,x.status,x.merchant_name,x.phone_number,x.category,x.sub_category,x.mcc,x.sub_first_date::date,
548	        x.check_sub_status,x.cancelled_at::date,x.expected_renewal_due_date::date,x.renewal_date::date,x.completed_ads_count::int,x.wallet_balance
549	      FROM jsonb_to_recordset(${sql.json(rows)}::jsonb) AS x(customer_id text,status text,merchant_name text,phone_number text,category text,sub_category text,mcc text,sub_first_date text,
550	        check_sub_status text,cancelled_at text,expected_renewal_due_date text,renewal_date text,completed_ads_count numeric,wallet_balance numeric)
551	      ON CONFLICT (sync_run_id,customer_id) DO UPDATE SET status=EXCLUDED.status,merchant_name=EXCLUDED.merchant_name,phone_number=EXCLUDED.phone_number,
552	        category=EXCLUDED.category,sub_category=EXCLUDED.sub_category,mcc=EXCLUDED.mcc,sub_first_date=EXCLUDED.sub_first_date,
553	        check_sub_status=EXCLUDED.check_sub_status,cancelled_at=EXCLUDED.cancelled_at,expected_renewal_due_date=EXCLUDED.expected_renewal_due_date,
554	        renewal_date=EXCLUDED.renewal_date,completed_ads_count=EXCLUDED.completed_ads_count,wallet_balance=EXCLUDED.wallet_balance
555	    `;
556	    return NextResponse.json({ok:true,accepted:rows.length,invalidRows:invalid});
557	  }
558	
559	  if(action==='ads'){
560	    const rows:any[]=[]; const invalid:number[]=[];
561	    for(const r of input){
562	      const id=custId(r.customerId); const status=String(r.adStatus||'').trim().toUpperCase();
563	      if(!id||!['ACTIVE','COMPLETED'].includes(status)){invalid.push(Number(r.sourceRow)||0);continue;}
564	      rows.push({customer_id:id,client_id:txt(r.clientId),mid:txt(r.mid),merchant_name:txt(r.merchantName),phone_number:txt(r.phone),category:txt(r.category),sub_category:txt(r.subCategory),
565	        onboarded_date:iso(r.onboardedDate),creative_name:txt(r.creativeName),description:txt(r.description),ad_status:status,budget:num(r.budget),start_date:iso(r.startDate),end_date:iso(r.endDate),
566	        impressions:num(r.impressions),clicks:num(r.clicks),ctr:num(r.ctr),reach:num(r.reach),spend:num(r.spend),source_row:Number(r.sourceRow)||null,
567	        ad_id:String(r.adId??'').trim()||null});
568	    }
569	    if(rows.length) await sql`
570	      INSERT INTO merchant_ads(sync_run_id,customer_id,client_id,mid,merchant_name,phone_number,category,sub_category,onboarded_date,creative_name,description,ad_status,budget,start_date,end_date,impressions,clicks,ctr,reach,spend,source_row,ad_id)
571	      SELECT ${runId},x.customer_id,x.client_id,x.mid,x.merchant_name,x.phone_number,x.category,x.sub_category,x.onboarded_date::date,x.creative_name,x.description,x.ad_status,
572	        x.budget,x.start_date::date,x.end_date::date,x.impressions,x.clicks,x.ctr,x.reach,x.spend,x.source_row,x.ad_id
573	      FROM jsonb_to_recordset(${sql.json(rows)}::jsonb) AS x(customer_id text,client_id text,mid text,merchant_name text,phone_number text,category text,sub_category text,onboarded_date text,
574	        creative_name text,description text,ad_status text,budget numeric,start_date text,end_date text,impressions numeric,clicks numeric,ctr numeric,reach numeric,spend numeric,source_row int,ad_id text)
575	    `;
576	    return NextResponse.json({ok:true,accepted:rows.length,invalidRows:invalid});
577	  }
578	
579	  if(action==='finish'){
580	    const counts=await sql`
581	      SELECT (SELECT count(*)::int FROM merchant_subscriptions WHERE sync_run_id=${runId}) AS subs,
582	             (SELECT count(*)::int FROM merchant_ads WHERE sync_run_id=${runId}) AS ads
583	    `;
584	    const subs=counts[0].subs, ads=counts[0].ads;
585	    const expectedSubs=Number(body?.expectedSubs), expectedAds=Number(body?.expectedAds);
586	    const fail=async(note:string)=>{
587	      await sql`UPDATE csm_sync_runs SET status='failed',finished_at=now(),subs_rows=${subs},ads_rows=${ads},note=${note} WHERE id=${runId}`;
588	      return NextResponse.json({error:note,subs,ads},{status:409});
589	    };
590	    if(subs!==expectedSubs||ads!==expectedAds) return fail(`Row counts do not match: received ${subs} subscriptions / ${ads} ads, script sent ${expectedSubs} / ${expectedAds}.`);
591	    const prev=await sql`SELECT subs_rows,ads_rows FROM csm_sync_runs WHERE status='complete' ORDER BY id DESC LIMIT 1`;
592	    if(prev[0]&&(subs<prev[0].subs_rows*0.5||ads<prev[0].ads_rows*0.5)) return fail(`Refusing: far fewer rows than the last sync (${prev[0].subs_rows} subscriptions / ${prev[0].ads_rows} ads).`);
593	    await sql`UPDATE csm_sync_runs SET status='complete',finished_at=now(),subs_rows=${subs},ads_rows=${ads} WHERE id=${runId}`;
594	    // Keep the two most recent complete runs; older snapshots are removed.
595	    await sql`
596	      DELETE FROM csm_sync_runs WHERE id NOT IN (SELECT id FROM csm_sync_runs WHERE status='complete' ORDER BY id DESC LIMIT 2)
597	        AND (status<>'running')
598	    `;
599	    // Fresh planner statistics: the snapshot tables are rebuilt daily.
600	    try{await sql`ANALYZE merchant_subscriptions`;await sql`ANALYZE merchant_ads`;}catch{}
601	    const allocation=await allocateUnassigned(sql,runId);
602	    // CSM WhatsApp nudges (T1–T5) from the fresh snapshot, after the response.
603	    after(async()=>{try{await ensureCsmWaRun(sql);}catch(e){console.error('csm whatsapp error',e);}});
604	    return NextResponse.json({ok:true,runId,subscriptions:subs,ads,newlyAssigned:allocation.assigned});
605	  }
606	
607	  return NextResponse.json({error:'Unknown action'},{status:400});
608	}
